from playwright.sync_api import sync_playwright
base=os.environ.get('UNITY_URL','http://127.0.0.1:3482')
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page(viewport={'width':390,'height':844});page.goto(base+'/baccarat/index.html');page.locator('[data-action=tables]').click();page.locator('[data-action="start:lounge"]').click();page.locator('[data-action="bet:player"]').click();page.locator('[data-action=confirm]').click();page.locator('#squeeze-dialog[open]').wait_for(timeout=15000);page.locator('#squeeze-range').fill('35');page.evaluate("()=>{Object.defineProperty(document,'hidden',{configurable:true,get:()=>true});document.dispatchEvent(new Event('visibilitychange'))}");assert not page.locator('#squeeze-dialog[open]').count();assert page.locator('[data-action=resume-deal]').is_visible();page.evaluate("()=>{delete document.hidden;document.dispatchEvent(new Event('visibilitychange'))}");page.locator('[data-action=resume-deal]').click();page.locator('#squeeze-dialog[open]').wait_for();assert page.locator('#squeeze-range').input_value()=='35';plan=page.evaluate('BACCARAT.session.state.round.presentation');page.locator('[data-show=hold]').click();page.locator('#settings-link').click();page.locator('[data-setting=presentation]').select_option('off');page.locator('[data-action=back]').click();page.locator('[data-action=resume-deal]').click();page.locator('#squeeze-dialog[open]').wait_for(timeout=3000);assert page.evaluate('BACCARAT.session.state.round.presentation')==plan;page.locator('[data-show=skip]').click();page.locator('[data-action=next]').click();page.locator('[data-action="bet:player"]').click();page.locator('[data-action=confirm]').click();assert page.evaluate('BACCARAT.session.state.round.presentation.mode')=='off';assert '演出OFF' in page.locator('.show-game-note').inner_text();page.wait_for_function("()=>BACCARAT.session.state.phase==='result'",timeout=6000);assert not page.locator('#squeeze-dialog[open]').count();page.evaluate("()=>{document.body.classList.add('reduced');const x=document.createElement('div');x.className='show-cutin';x.dataset.tier='rainbow';x.innerHTML='<span class=\"cutin-line\">text</span>';document.body.append(x)}");assert page.locator('.cutin-line').evaluate('x=>getComputedStyle(x).animationName')=='none';b.close();print('frozen mode, simulated hidden/return handler and reduced rainbow passed')
